begin
 if current_user<>'supabase_admin' or not exists(select 1 from pg_roles where rolname=current_user and rolsuper)
 or current_setting('server_version_num')::integer<150000 or current_setting('server_version_num')::integer>=190000
 or current_setting('transaction_read_only')<>'off'
 then raise exception 'PRM_FINAL_CONTEXT_MISMATCH'; end if;
 if not exists(select 1 from pg_roles where rolname='service_role' and not rolsuper and rolbypassrls)
 or not has_schema_privilege('authenticated','public','USAGE') or not has_schema_privilege('service_role','public','USAGE')
 or (select count(*) from pg_roles where rolname in('anon','authenticated','service_role'))<>3
 or exists(select 1 from pg_roles where rolname in('anon','authenticated') and (rolsuper or rolbypassrls or not rolinherit))
 or exists(select 1 from pg_roles a join pg_roles b on b.oid<>a.oid where a.rolname in('anon','authenticated') and pg_has_role(a.oid,b.oid,'USAGE'))
 then raise exception 'PRM_ROLE_DRIFT'; end if;
 -- Validate the recursive footprint before locks and again below; do not widen it at runtime.
 actual_footprint:=(with recursive lock_nodes(oid) as (
 select to_regclass(root_item->>'key') from jsonb_array_elements(scope) root_item
 union
 select dep.refobjid from lock_nodes ln join pg_class parent_rel on parent_rel.oid=ln.oid and parent_rel.relkind='v'
 join pg_rewrite rw on rw.ev_class=ln.oid join pg_depend dep on dep.classid='pg_catalog.pg_rewrite'::regclass and dep.objid=rw.oid and dep.refclassid='pg_catalog.pg_class'::regclass
 join pg_class child_rel on child_rel.oid=dep.refobjid and child_rel.relkind in('r','p','v')
 ) select coalesce(jsonb_agg(lock_ns.nspname||'.'||lock_rel.relname order by lock_ns.nspname,lock_rel.relname),'[]'::jsonb)
 from lock_nodes ln join pg_class lock_rel on lock_rel.oid=ln.oid join pg_namespace lock_ns on lock_ns.oid=lock_rel.relnamespace);
 if actual_footprint<>footprint_contract then raise exception 'PRM_FINAL_LOCK_FOOTPRINT_DRIFT'; end if;
 -- Real execution additionally requires an operator-enforced DDL/DCL-free window.
 for s in select * from jsonb_to_recordset(scope) t(key text,kind text,authenticated jsonb) order by key loop
  if to_regclass(s.key) is null then raise exception 'PRM_OBJECT_DRIFT'; end if;
  execute format('lock table %s in access exclusive mode',s.key::regclass);
 end loop;
 for s in select * from jsonb_to_recordset(scope) t(key text,kind text,authenticated jsonb) order by key loop
  select r.*,o.rolname owner_name into c from pg_class r join pg_roles o on o.oid=r.relowner where r.oid=to_regclass(s.key);
  if c.relkind::text<>s.kind or c.owner_name<>'supabase_admin' or c.relforcerowsecurity
   or (s.kind='r' and not c.relrowsecurity) or (s.kind='v' and not coalesce(c.reloptions @> array['security_invoker=true'],false))
  then raise exception 'PRM_OBJECT_DRIFT'; end if;
  if exists(select 1 from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped and a.attacl is not null)
  or exists(select 1 from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a left join pg_roles r on r.oid=a.grantee
    where a.grantee=0 or r.rolname not in('supabase_admin','postgres','service_role','anon','authenticated')
      or (r.rolname in('anon','authenticated') and (a.grantor<>c.relowner or a.is_grantable)))
  then raise exception 'PRM_ACL_SOURCE_DRIFT'; end if;
  actual_columns:=(select coalesce(jsonb_agg(jsonb_build_object('name',att.attname,'type',typ_ns.nspname||'.'||typ.typname,'typmod',att.atttypmod,'notNull',att.attnotnull) order by att.attnum),'[]'::jsonb) from pg_attribute att join pg_type typ on typ.oid=att.atttypid join pg_namespace typ_ns on typ_ns.oid=typ.typnamespace where att.attrelid=c.oid and att.attnum>0 and not att.attisdropped);
  if actual_columns is distinct from (select x->'columns' from jsonb_array_elements(columns_contract) x where x->>'key'=s.key)
  then raise exception 'PRM_FINAL_COLUMNS_DRIFT'; end if;
  if s.key in(select x->>'key' from jsonb_array_elements(views_contract) x)
  and not exists(select 1 from jsonb_array_elements(views_contract) x where x->>'key'=s.key and (x->'rawHashes') ? md5(pg_get_viewdef(c.oid,false)))
  then raise exception 'PRM_FINAL_ACCEPTED_VIEW_DRIFT'; end if;
  if exists(select 1 from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) acl_item join pg_roles human_role on human_role.oid=acl_item.grantee
    where human_role.rolname in('anon','authenticated') and acl_item.privilege_type not in('DELETE','INSERT','REFERENCES','SELECT','TRIGGER','TRUNCATE','UPDATE'))
  then raise exception 'PRM_FINAL_UNEXPECTED_PRIVILEGE'; end if;
  foreach role_name in array array['anon','authenticated'] loop
   select oid into role_oid from pg_roles where rolname=role_name;
   expected:=case when role_name='anon' then '[]'::jsonb else s.authenticated end;
   if exists(select 1 from jsonb_array_elements_text(expected) p where not has_table_privilege(role_oid,c.oid,p))
   then raise exception 'PRM_LEGITIMATE_ACCESS_MISSING'; end if;
  end loop;
 end loop;
