 select to_regclass(root_item->>'key') from jsonb_array_elements(scope) root_item
 union
 select dep.refobjid from lock_nodes ln join pg_class parent_rel on parent_rel.oid=ln.oid and parent_rel.relkind='v'
 join pg_rewrite rw on rw.ev_class=ln.oid join pg_depend dep on dep.classid='pg_catalog.pg_rewrite'::regclass and dep.objid=rw.oid and dep.refclassid='pg_catalog.pg_class'::regclass
 join pg_class child_rel on child_rel.oid=dep.refobjid and child_rel.relkind in('r','p','v')
 ) select coalesce(jsonb_agg(lock_ns.nspname||'.'||lock_rel.relname order by lock_ns.nspname,lock_rel.relname),'[]'::jsonb)
