 'acl',(select coalesce(jsonb_agg(x::text order by x::text),'[]'::jsonb) from aclexplode(coalesce(_catalog_relation.relacl,acldefault('r',_catalog_relation.relowner))) x where x.grantee not in(select oid from pg_roles where rolname in('anon','authenticated'))),
 'view',case when _catalog_relation.relkind='v' then md5(pg_get_viewdef(_catalog_relation.oid,false)) else null end,
 'columns',(select jsonb_agg(a::text order by a.attnum) from pg_attribute a where a.attrelid=_catalog_relation.oid and a.attnum>0 and not a.attisdropped)) order by _scope_entry.key)
 from jsonb_to_recordset(scope) _scope_entry(key text,kind text,authenticated jsonb) join pg_class _catalog_relation on _catalog_relation.oid=to_regclass(_scope_entry.key)),
 'policies',(select md5(string_agg(p::text,'|' order by p.oid)) from pg_policy p),
 'functions',(select md5(string_agg(p::text,'|' order by p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','storage')),
 'defaults',(select md5(string_agg(d::text,'|' order by d.oid)) from pg_default_acl d),
 'memberships',(select md5(string_agg(m::text,'|' order by m.member,m.roleid)) from pg_auth_members m),
 'role_flags',(select md5(string_agg(jsonb_build_object('name',role_meta.rolname,'superuser',role_meta.rolsuper,'inherit',role_meta.rolinherit,'bypass',role_meta.rolbypassrls,'createRole',role_meta.rolcreaterole,'createDb',role_meta.rolcreatedb,'login',role_meta.rolcanlogin)::text,'|' order by role_meta.rolname)) from pg_roles role_meta where role_meta.rolname in('anon','authenticated','service_role','postgres','supabase_admin','authenticator','supabase_auth_admin','supabase_storage_admin','pg_database_owner')),
 'schema_acl',(select md5(string_agg(jsonb_build_object('name',schema_meta.nspname,'owner',schema_meta.nspowner,'acl',schema_meta.nspacl)::text,'|' order by schema_meta.nspname)) from pg_namespace schema_meta where schema_meta.nspname in('public','auth','storage')),
 'storage_columns',(select md5(string_agg(storage_attr::text,'|' order by storage_attr.attrelid,storage_attr.attnum)) from pg_attribute storage_attr join pg_class storage_rel on storage_rel.oid=storage_attr.attrelid join pg_namespace storage_ns on storage_ns.oid=storage_rel.relnamespace where storage_ns.nspname='storage' and storage_attr.attnum>0 and not storage_attr.attisdropped),
 'storage_constraints',(select md5(string_agg(jsonb_build_object('relation',storage_cons.conrelid,'name',storage_cons.conname,'definition',pg_get_constraintdef(storage_cons.oid),'validated',storage_cons.convalidated)::text,'|' order by storage_cons.oid)) from pg_constraint storage_cons join pg_class storage_rel on storage_rel.oid=storage_cons.conrelid join pg_namespace storage_ns on storage_ns.oid=storage_rel.relnamespace where storage_ns.nspname='storage'),
 'storage_indexes',(select md5(string_agg(pg_get_indexdef(storage_idx.indexrelid),'|' order by storage_idx.indexrelid)) from pg_index storage_idx join pg_class storage_rel on storage_rel.oid=storage_idx.indrelid join pg_namespace storage_ns on storage_ns.oid=storage_rel.relnamespace where storage_ns.nspname='storage'),
 'storage_triggers',(select md5(string_agg(jsonb_build_object('relation',storage_tg.tgrelid,'name',storage_tg.tgname,'enabled',storage_tg.tgenabled,'definition',pg_get_triggerdef(storage_tg.oid))::text,'|' order by storage_tg.oid)) from pg_trigger storage_tg join pg_class storage_rel on storage_rel.oid=storage_tg.tgrelid join pg_namespace storage_ns on storage_ns.oid=storage_rel.relnamespace where storage_ns.nspname='storage'),
 'storage',(select md5(string_agg(jsonb_build_object('name',_catalog_relation.relname,'kind',_catalog_relation.relkind,'owner',_catalog_relation.relowner,'rls',_catalog_relation.relrowsecurity,'force',_catalog_relation.relforcerowsecurity,'options',_catalog_relation.reloptions,'acl',_catalog_relation.relacl)::text,'|' order by _catalog_relation.oid)) from pg_class _catalog_relation join pg_namespace n on n.oid=_catalog_relation.relnamespace where n.nspname='storage')
);
 if protected_before is distinct from protected_after then raise exception 'PRM_PRESERVATION_FAILED'; end if;
 for s in select * from jsonb_to_recordset(scope) t(key text,kind text,authenticated jsonb) order by key loop
  foreach role_name in array array['anon','authenticated'] loop
   expected:=case when role_name='anon' then '[]'::jsonb else s.authenticated end;
   select coalesce(array_agg(p order by p),array[]::text[]) into current_access
    from unnest(array['DELETE','INSERT','REFERENCES','SELECT','TRIGGER','TRUNCATE','UPDATE']) p where has_table_privilege(role_name,s.key,p);
   if to_jsonb(current_access)<>expected then raise exception 'PRM_POSTFLIGHT_FAILED'; end if;
  end loop;
 end loop;
 perform set_config('pipeline_os.prm1_receipt',jsonb_build_object(
 'protocol','PRM-FINAL-r1','ordinal','048','contractSha256','3c883ea1c38971ac4af058c7800166d3ba0b846a97a228ad85025138b59a1a1e','stage','checked_before_commit',
 'relations',28,'protectedBefore',md5(protected_before::text),'protectedAfter',md5(protected_after::text),
 'preservationMatches',protected_before=protected_after,'version',current_setting('server_version_num'))::text,true);
end $prm$;
select current_setting('pipeline_os.prm1_receipt')::jsonb pipeline_os_prm1_application;
commit;
